<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>SkyePay | SkyeGateFS27</title>
  <meta name="description" content="SkyePay is the SkyeGateFS27 free trial, Stripe checkout, and automatic workspace activation route." />
  <link rel="canonical" href="https://skyesol.netlify.app/skyepay.html" />
  <link rel="stylesheet" href="assets/skyepay.css" />
  <script type="importmap">
  {"imports":{"gsap":"https://esm.sh/gsap@3.15.0","gsap/ScrollTrigger":"https://esm.sh/gsap@3.15.0/ScrollTrigger","lenis":"https://esm.sh/lenis@1.3.23"}}
  </script>
  <script src="assets/skyepay.js" defer></script>
  <script type="module" src="assets/skyepay-motion.mjs" async></script>
</head>
<body>
  <div class="motion-progress" aria-hidden="true"><span id="skypayProgress"></span></div>
  <div class="cursor-glow" id="cursorGlow" aria-hidden="true"></div>
  <div class="scanline" aria-hidden="true"></div>

  <header class="pay-nav">
    <a class="pay-brand neon-magnetic" href="index.html" aria-label="Back to SkyeGateFS27">
      <img src="https://cdn1.sharemyimage.com/2026/02/16/logo1_transparent.png" alt="SkyeGateFS27" />
      <span>SkyePay</span>
    </a>
    <nav>
      <a href="#checkout">Checkout</a>
      <a href="skyepay-store.html">Store</a>
      <a href="#gate-path">Gate Path</a>
      <a href="skyepay-admin.html">Ledger</a>
    </nav>
  </header>

  <main>
    <section class="pay-hero" id="checkout">
      <div class="hero-copy">
        <p class="eyebrow" id="clientEyebrow">Private preview closeout</p>
        <h1 id="heroTitle"><span class="neon-gradient-text text-effects">SkyePay</span> turns confirmed payment into an automatic workspace unlock.</h1>
        <p class="lead" id="heroLead">I do not sell brochure pages. I build sovereign technology: full stack apps, integrated artificial intelligence, Stripe-backed checkout, vault limits, and the gate record that keeps each client route controlled.</p>
        <div class="hero-points" id="heroPoints" aria-label="SkyePay route">
          <span>$0 today trials</span>
          <span>Stripe Checkout</span>
          <span>Vault access limits</span>
          <span>Workspace unlock</span>
        </div>
      </div>

      <section class="checkout-console" aria-labelledby="checkoutTitle">
        <div class="console-head">
          <div>
            <p class="eyebrow">Client lane</p>
            <h2 id="checkoutTitle">Continue the private app preview</h2>
          </div>
          <span class="live-badge" id="proofModeBadge">Stripe backed</span>
        </div>

        <div class="client-strip">
          <div>
            <span class="mini-label">Client</span>
            <strong id="clientName">Loading...</strong>
          </div>
          <div>
            <span class="mini-label">Free tester access</span>
            <strong id="trialDays">7 days</strong>
          </div>
          <div>
            <span class="mini-label">Approval</span>
            <strong>Owner gated</strong>
          </div>
        </div>

        <form id="skypayForm" class="pay-form">
          <label>
            Your name
            <input name="customer_name" autocomplete="name" placeholder="Bob" required />
          </label>
          <label>
            Email for receipt
            <input name="customer_email" type="email" autocomplete="email" placeholder="owner@company.com" required />
          </label>
          <label>
            Company
            <input name="company_name" autocomplete="organization" placeholder="Bob's Smoke Shop" />
          </label>

          <div class="offer-select" id="offerSelect" aria-label="SkyePay offers"></div>

          <button class="primary-action neon-magnetic" type="submit" id="checkoutBtn">
            Start secure trial
          </button>
          <p class="fine-print" id="clientSpecial">Free preview first. Confirmed Stripe payment unlocks the workspace automatically.</p>
        </form>
        <div class="client-contact" id="clientContact" hidden></div>

        <div class="status-panel" id="statusPanel" hidden>
          <p class="eyebrow">Payment status</p>
          <h3 id="statusTitle">Pending</h3>
          <p id="statusText">SkyePay is checking the gate ledger.</p>
        </div>
      </section>
    </section>

    <section class="usage-band skypay-reveal" id="included">
      <div>
        <p class="eyebrow">Included during preview</p>
        <h2 id="includedTitle">The client gets to feel included before they pay.</h2>
      </div>
      <ul id="includedUsage">
        <li>Private app preview</li>
        <li>Owner approval before paid activation</li>
        <li>Workspace handoff after closeout</li>
      </ul>
    </section>

    <section class="gate-path skypay-reveal" id="gate-path">
      <p class="eyebrow" id="gateEyebrow">SkyeGateFS27 route</p>
      <h2 id="gateTitle">Payment is not the end. It is the gate event that starts controlled activation.</h2>
      <div class="path-rail" id="pathRail">
        <article>
          <span>01</span>
          <h3>Preview accepted</h3>
        <p>The client chooses to continue from the private app preview through a controlled app lane instead of a loose external payment link.</p>
        </article>
        <article>
          <span>02</span>
          <h3>Stripe Checkout</h3>
          <p>SkyePay creates a Checkout Session with approved catalog metadata, zero-up-front trial terms, and no card data touching the app.</p>
        </article>
        <article>
          <span>03</span>
          <h3>Gate ledger</h3>
          <p>The webhook writes the confirmed payment or trial state into FS27 and unlocks the workspace automatically.</p>
        </article>
        <article>
          <span>04</span>
          <h3>Owner approval</h3>
          <p>You can still void, audit, or manually correct the workspace from the SkyePay ledger.</p>
        </article>
        <article>
          <span>05</span>
          <h3>Repo platforms</h3>
          <p>After live proof, the last lane is wiring the repo platforms into SkyePay as billable app routes.</p>
        </article>
      </div>
    </section>
  </main>
</body>
</html>


CSS SOURCE

:root {
  --sky-bg: #07080c;
  --sky-panel: rgba(13, 16, 24, 0.86);
  --sky-panel-2: rgba(22, 24, 32, 0.72);
  --sky-line: rgba(255, 255, 255, 0.14);
  --sky-text: rgba(255, 255, 255, 0.94);
  --sky-muted: rgba(255, 255, 255, 0.68);
  --sky-soft: rgba(255, 255, 255, 0.48);
  --sky-gold: #f6c14b;
  --sky-cyan: #27f2ff;
  --sky-rose: #ff5f8f;
  --sky-green: #74f2a7;
  --sky-purple: #8a4fff;
  --sky-shadow: 0 22px 70px rgba(0, 0, 0, 0.46);
  --sky-sans: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html { min-height: 100%; background: var(--sky-bg); }
body {
  min-height: 100%;
  margin: 0;
  color: var(--sky-text);
  font-family: var(--sky-sans);
  background:
    linear-gradient(115deg, rgba(7, 8, 12, 0.98), rgba(14, 14, 20, 0.94) 44%, rgba(6, 12, 14, 0.98)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.04) 0 1px, transparent 1px 92px),
    repeating-linear-gradient(0deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 92px);
  overflow-x: hidden;
}

body,
.hero-copy,
.checkout-console,
.usage-band,
.gate-path {
  opacity: 1;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(140deg, rgba(246, 193, 75, 0.08), transparent 32%),
    linear-gradient(300deg, rgba(39, 242, 255, 0.08), transparent 38%),
    linear-gradient(20deg, transparent, rgba(255, 95, 143, 0.06) 62%, transparent 88%);
  z-index: -2;
}

.motion-progress {
  position: fixed;
  inset: 0 0 auto 0;
  height: 4px;
  z-index: 100;
  background: rgba(255,255,255,0.06);
}
.motion-progress span {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--sky-gold), var(--sky-cyan), var(--sky-rose));
  box-shadow: 0 0 24px rgba(39, 242, 255, 0.52);
}

.cursor-glow {
  position: fixed;
  left: 0;
  top: 0;
  width: 220px;
  height: 220px;
  pointer-events: none;
  transform: translate3d(-50%, -50%, 0);
  background: radial-gradient(circle, rgba(39, 242, 255, 0.15), rgba(246, 193, 75, 0.08) 32%, transparent 66%);
  mix-blend-mode: screen;
  z-index: 2;
}

.scanline {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background: linear-gradient(180deg, transparent, rgba(255,255,255,0.035), transparent);
  height: 180px;
  animation: scan 8s linear infinite;
}

@keyframes scan {
  0% { transform: translateY(-200px); }
  100% { transform: translateY(calc(100vh + 200px)); }
}

::-webkit-scrollbar { width: 14px; }
::-webkit-scrollbar-track {
  background: rgba(255,255,255,0.075);
  border-left: 1px solid rgba(39, 242, 255, 0.18);
  box-shadow: inset 0 0 16px rgba(39, 242, 255, 0.14);
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--sky-cyan), var(--sky-gold), var(--sky-rose));
  border: 3px solid rgba(7,8,12,0.92);
  border-radius: 999px;
  box-shadow: 0 0 18px rgba(39, 242, 255, 0.5);
}

a { color: inherit; }
.pay-nav {
  position: sticky;
  top: 4px;
  z-index: 50;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  width: min(1180px, calc(100% - 28px));
  margin: 14px auto 0;
  padding: 10px 12px;
  border: 1px solid var(--sky-line);
  background: rgba(7, 8, 12, 0.76);
  backdrop-filter: blur(16px);
  box-shadow: var(--sky-shadow);
}

.pay-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  font-weight: 900;
}
.pay-brand img {
  width: 42px;
  height: 42px;
  object-fit: contain;
}
.pay-brand span {
  font-size: 15px;
  letter-spacing: 0;
}
.pay-nav nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}
.pay-nav nav a {
  padding: 8px 10px;
  border: 1px solid transparent;
  text-decoration: none;
  color: var(--sky-muted);
  font-size: 13px;
}
.pay-nav nav a:hover {
  color: var(--sky-text);
  border-color: var(--sky-line);
}

main {
  width: min(1180px, calc(100% - 28px));
  margin: 0 auto;
  position: relative;
  z-index: 3;
}

.pay-hero {
  min-height: calc(100vh - 82px);
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(340px, 0.96fr);
  gap: 22px;
  align-items: center;
  padding: 44px 0 32px;
}

.hero-copy {
  max-width: 720px;
}
.eyebrow {
  margin: 0 0 10px;
  color: var(--sky-cyan);
  font-size: 12px;
  text-transform: uppercase;
  font-weight: 900;
  letter-spacing: 0;
}
h1, h2, h3, p { letter-spacing: 0; }
h1 {
  margin: 0;
  font-size: clamp(42px, 6vw, 84px);
  line-height: 0.94;
  font-weight: 950;
  max-width: 650px;
  overflow-wrap: normal;
  color: var(--sky-text);
}
.neon-gradient-text {
  color: transparent;
  background: linear-gradient(90deg, var(--sky-gold), var(--sky-cyan), var(--sky-rose));
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 18px rgba(39, 242, 255, 0.14));
  animation: skypayTextShimmer 5.4s ease-in-out infinite alternate;
}
.text-effects {
  position: relative;
  isolation: isolate;
  text-shadow: 0 0 24px rgba(39, 242, 255, 0.16);
}
.text-effects::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -0.08em;
  height: 0.07em;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(246,193,75,0), rgba(246,193,75,0.9), rgba(39,242,255,0.86), rgba(255,95,143,0));
  filter: blur(0.5px);
  animation: textEffectUnderline 4.8s ease-in-out infinite;
}

@keyframes skypayTextShimmer {
  0% { background-position: 0% 50%; filter: drop-shadow(0 0 12px rgba(246, 193, 75, 0.12)); }
  100% { background-position: 100% 50%; filter: drop-shadow(0 0 24px rgba(39, 242, 255, 0.2)); }
}
@keyframes textEffectUnderline {
  0%, 100% { transform: scaleX(0.28); opacity: 0.52; }
  48% { transform: scaleX(1); opacity: 0.95; }
}
h2 {
  margin: 0;
  font-size: clamp(24px, 4vw, 48px);
  line-height: 1.02;
}
h3 {
  margin: 0;
  font-size: 17px;
}
.lead {
  max-width: 680px;
  color: rgba(255, 255, 255, 0.76);
  font-size: clamp(16px, 2.1vw, 20px);
  line-height: 1.55;
}
.hero-points {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}
.hero-points span,
.live-badge,
.mini-label {
  border: 1px solid var(--sky-line);
  background: rgba(255,255,255,0.055);
  padding: 7px 9px;
  font-size: 12px;
  color: var(--sky-muted);
}

.checkout-console,
.usage-band,
.gate-path,
.ledger-login,
.ledger-panel {
  border: 1px solid var(--sky-line);
  background: var(--sky-panel);
  box-shadow: var(--sky-shadow);
  backdrop-filter: blur(20px);
}
.checkout-console {
  padding: 18px;
}
.console-head {
  display: flex;
